// گام ۱ — بررسی توکن و تکه‌تکه‌کردن پایان‌نامه (الگوی map-reduce، مثل عامل اعتبارسنجی).
// برای هر تکه از مدل می‌خواهیم مثل یک «داور جلسه‌ی دفاع» پرسش و نقطه‌ضعف پیدا کند و برای هرکدام
// جمله‌ای را عیناً از متن نقل کند؛ پورتال بعداً همان نقل‌قول را در متن واقعی راستی‌آزمایی می‌کند.
const req = $input.first().json;
if (!$env.AGENT_TOKEN || (req.headers || {})['x-agent-token'] !== $env.AGENT_TOKEN) {
  throw new Error('Unauthorized: invalid X-Agent-Token');
}
const body = req.body || {};
const text = String((body.thesis || {}).text || '');
const proposal = String((body.proposal || {}).excerpt || '').slice(0, Number($env.DEFENSE_PROPOSAL_CHARS) || 2500);
const categories = Array.isArray(body.categories) ? body.categories : [];
const SIZE = Number($env.DEFENSE_WINDOW_CHARS) || 6000;
const OVERLAP = 300;

const windows = [];
for (let start = 0; start < text.length; start += SIZE - OVERLAP) {
  windows.push(text.slice(start, start + SIZE));
  if (start + SIZE >= text.length) break;
}

const list = categories.map((c) => `- ${c.key}: ${c.label} — ${c.hint}`).join('\n');
const system = [
  'تو یکی از داوران جلسه‌ی دفاع پروژه‌ی کارشناسی مهندسی کامپیوتر در دانشگاه صنعتی امیرکبیر هستی.',
  'ورودی: دسته‌های پرسش، خلاصه‌ی پیشنهاد پروژه (آن‌چه دانشجو وعده داده بود) و «یک تکه» از متن پایان‌نامه.',
  'وظیفه: فقط بر پایه‌ی همین تکه، پرسش‌هایی که یک داور دقیق در جلسه می‌پرسد و نقاط ضعفی که به آن‌ها ایراد می‌گیرد را پیدا کن.',
  'قواعد:',
  '۱. حداکثر ۴ پرسش و ۲ نقطه‌ضعف. پرسش باید مشخص و مربوط به همین متن باشد، نه کلی (مثلاً «چرا آستانه‌ی ۰٫۷ را انتخاب کردید؟» نه «روش خود را توضیح دهید»).',
  '۲. برای هر مورد، evidence را عیناً و بدون تغییر از متن همین تکه رونویسی کن (۸ تا ۲۰ واژه). برای دسته‌ی proposal_gap می‌توانی از متن پیشنهاد نقل کنی.',
  '۳. category فقط یکی از کلیدهای انگلیسی دسته‌هاست. severity یکی از high، medium، low است.',
  '۴. اگر این تکه فقط فهرست مطالب، مراجع یا مشخصات است و چیز قابل‌پرسشی ندارد، فهرست‌ها را خالی برگردان.',
  '۵. همه‌ی متن‌ها فارسی باشد.',
  'خروجی فقط یک شیء JSON با همین شکل باشد و هیچ متن دیگری ننویس:',
  '{"questions": [{"category": "method", "question": "...", "why": "<چرا داور این را می‌پرسد، یک جمله>", "evidence": "<نقل‌قول عینی>"}],',
  ' "weak_points": [{"title": "...", "detail": "<یک یا دو جمله>", "suggestion": "<دانشجو چه کند>", "severity": "medium", "evidence": "<نقل‌قول عینی>"}]}',
].join('\n');

return windows.map((windowText, index) => ({
  json: {
    prep_id: body.prep_id,
    result_path: body.result_path,
    max_questions: Number(body.max_questions) || 12,
    max_weak_points: Number(body.max_weak_points) || 6,
    categories: categories.map((c) => c.key),
    window_index: index,
    window_count: windows.length,
    llm_request: {
      model: $env.LLM_CHAT_MODEL,
      temperature: 0.2,
      stream: false,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        {
          role: 'user',
          content:
            `عنوان: ${(body.case || {}).title_fa || ''}\n\nدسته‌های پرسش:\n${list}\n\n` +
            `خلاصه‌ی پیشنهاد پروژه:\n"""\n${proposal || '(در دسترس نیست)'}\n"""\n\n` +
            `متن پایان‌نامه (تکه‌ی ${index + 1} از ${windows.length}):\n"""\n${windowText}\n"""`,
        },
      ],
    },
  },
}));

// گام ۳ — گردآوری نامزدها از همه‌ی تکه‌ها و ساختن درخواست «گزینش نهایی».
// مدل در گام بعد فقط «شماره‌ی» نامزدها را برمی‌گزیند و می‌تواند متن پرسش را روان‌تر کند، اما
// نقل‌قول هر مورد همان نقل‌قول اصلی تکه می‌ماند؛ پس گزینش نهایی نمی‌تواند شاهد تازه بسازد.
const windows = $('Split Into Windows').all();
const responses = $input.all();
const first = windows[0].json;

function parseJson(content) {
  const clean = String(content).replace(/<think>[\s\S]*?<\/think>/g, '');
  const start = clean.indexOf('{');
  const end = clean.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('no JSON object');
  return JSON.parse(clean.slice(start, end + 1));
}
const str = (v, n) => String(v || '').replace(/\s+/g, ' ').trim().slice(0, n);

const questions = [];
const weak = [];
let failed = 0;
let lastError = '';
responses.forEach((item, i) => {
  const res = item.json || {};
  const content = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
  let parsed = null;
  if (content) {
    try { parsed = parseJson(content); } catch (e) { lastError = 'خروجی مدل JSON معتبر نبود'; }
  } else {
    const err = res.error;
    lastError = (err && (err.message || (typeof err === 'string' ? err : JSON.stringify(err)))) || 'پاسخ خالی از مدل';
  }
  if (!parsed || typeof parsed !== 'object') { failed += 1; return; }
  for (const q of Array.isArray(parsed.questions) ? parsed.questions.slice(0, 6) : []) {
    if (!q || !str(q.question, 400)) continue;
    questions.push({ n: questions.length + 1, category: str(q.category, 30), question: str(q.question, 400),
                     why: str(q.why, 500), evidence: str(q.evidence, 300), window: i + 1 });
  }
  for (const w of Array.isArray(parsed.weak_points) ? parsed.weak_points.slice(0, 3) : []) {
    if (!w || !str(w.title, 200)) continue;
    weak.push({ n: weak.length + 1, title: str(w.title, 200), detail: str(w.detail, 600),
                suggestion: str(w.suggestion, 600), severity: str(w.severity, 10),
                evidence: str(w.evidence, 300), window: i + 1 });
  }
});

const model = $env.LLM_CHAT_MODEL;
const error = failed === windows.length
  ? { error: 'مدل زبانی پاسخ قابل‌استفاده‌ای نداد.', detail: String(lastError).slice(0, 300), model }
  : null;

const listQ = questions.map((q) => `Q${q.n} [${q.category}] ${q.question}`).join('\n');
const listW = weak.map((w) => `W${w.n} [${w.severity}] ${w.title}: ${w.detail}`).join('\n');
const system = [
  'تو رئیس جلسه‌ی دفاع پروژه‌ی کارشناسی هستی و باید از میان پرسش‌ها و نقاط ضعفی که داوران پیشنهاد داده‌اند، مهم‌ترین‌ها را برگزینی.',
  `قواعد: حداکثر ${first.max_questions} پرسش و ${first.max_weak_points} نقطه‌ضعف. پرسش‌های تکراری یا هم‌معنا را یکی کن. ` +
    'تا جای ممکن از همه‌ی دسته‌ها پرسش بیاور و پرسش‌هایی را ترجیح بده که در جلسه‌ی واقعی بیشتر پرسیده می‌شوند.',
  'می‌توانی متن پرسش را کوتاه‌تر و روان‌تر کنی، اما معنایش را عوض نکن. فقط شماره‌های موجود در فهرست را برگردان.',
  'خروجی فقط یک شیء JSON با همین شکل:',
  '{"questions": [{"n": 3, "question": "<متن نهایی پرسش>"}], "weak_points": [{"n": 2}]}',
].join('\n');

return [{
  json: {
    prep_id: first.prep_id,
    result_path: first.result_path,
    max_questions: first.max_questions,
    max_weak_points: first.max_weak_points,
    windows: windows.length,
    failed_windows: failed,
    error,
    candidates: { questions, weak_points: weak },
    llm_request: {
      model,
      temperature: 0,
      stream: false,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: `پرسش‌های پیشنهادی:\n${listQ || '(هیچ)'}\n\nنقاط ضعف پیشنهادی:\n${listW || '(هیچ)'}` },
      ],
    },
  },
}];

// گام ۵ — ساختن نتیجه‌ی نهایی. اگر گزینش نهایی ناموفق بود، نامزدها به نوبت از هر دسته
// برداشته می‌شوند (پس خرابی این گام فقط کیفیت گزینش را کم می‌کند، نه کل نتیجه را).
const c = $('Collect Candidates').first().json;
const model = $env.LLM_CHAT_MODEL;
if (c.error) {
  return [{ json: { result_path: c.result_path, result: c.error } }];
}
const { questions, weak_points } = c.candidates;
if (!questions.length && !weak_points.length) {
  return [{ json: { result_path: c.result_path,
    result: { error: 'مدل زبانی در متن پایان‌نامه پرسش یا نکته‌ای پیدا نکرد.', model } } }];
}

function parseJson(content) {
  const clean = String(content).replace(/<think>[\s\S]*?<\/think>/g, '');
  const start = clean.indexOf('{');
  const end = clean.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('no JSON object');
  return JSON.parse(clean.slice(start, end + 1));
}

let picked = null;
const res = $input.first().json || {};
const content = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
try { picked = content ? parseJson(content) : null; } catch (e) { picked = null; }

const byQ = Object.fromEntries(questions.map((q) => [q.n, q]));
const byW = Object.fromEntries(weak_points.map((w) => [w.n, w]));
let outQ = [];
let outW = [];
if (picked && Array.isArray(picked.questions) && picked.questions.length) {
  const used = new Set();
  for (const p of picked.questions) {
    const q = byQ[Number(p && p.n)];
    if (!q || used.has(q.n)) continue;
    used.add(q.n);
    const text = String((p && p.question) || '').replace(/\s+/g, ' ').trim();
    outQ.push({ ...q, question: text.length >= 10 ? text.slice(0, 400) : q.question });
  }
  for (const p of Array.isArray(picked.weak_points) ? picked.weak_points : []) {
    const w = byW[Number(p && p.n)];
    if (w && !outW.includes(w)) outW.push(w);
  }
}
if (!outQ.length) {
  // نوبتی از هر دسته
  const groups = {};
  for (const q of questions) (groups[q.category] = groups[q.category] || []).push(q);
  const lists = Object.values(groups);
  for (let i = 0; outQ.length < c.max_questions && lists.some((l) => l.length > i); i += 1) {
    for (const l of lists) if (l[i] && outQ.length < c.max_questions) outQ.push(l[i]);
  }
}
if (!outW.length) {
  const rank = { high: 0, medium: 1, low: 2 };
  outW = [...weak_points].sort((a, b) => (rank[a.severity] ?? 1) - (rank[b.severity] ?? 1));
}

const strip = ({ n, window, ...rest }) => rest;
return [{
  json: {
    result_path: c.result_path,
    result: {
      questions: outQ.slice(0, c.max_questions).map(strip),
      weak_points: outW.slice(0, c.max_weak_points).map(strip),
      windows: c.windows,
      failed_windows: c.failed_windows,
      model,
    },
  },
}];
